import{assert as A}from"./asserts.js";const M=new Array(6);export function create(){return[1,0,0,1,0,0]}export function reset(n){return set(n,1,0,0,1,0,0)}export function multiply(n,c){const e=n[0],t=n[1],i=n[2],u=n[3],p=n[4],x=n[5],o=c[0],h=c[1],b=c[2],l=c[3],S=c[4],v=c[5];return n[0]=e*o+i*h,n[1]=t*o+u*h,n[2]=e*b+i*l,n[3]=t*b+u*l,n[4]=e*S+i*v+p,n[5]=t*S+u*v+x,n}export function set(n,c,e,t,i,u,p){return n[0]=c,n[1]=e,n[2]=t,n[3]=i,n[4]=u,n[5]=p,n}export function setFromArray(n,c){return n[0]=c[0],n[1]=c[1],n[2]=c[2],n[3]=c[3],n[4]=c[4],n[5]=c[5],n}export function apply(n,c){const e=c[0],t=c[1];return c[0]=n[0]*e+n[2]*t+n[4],c[1]=n[1]*e+n[3]*t+n[5],c}export function rotate(n,c){const e=Math.cos(c),t=Math.sin(c);return multiply(n,set(M,e,t,-t,e,0,0))}export function scale(n,c,e){return multiply(n,set(M,c,0,0,e,0,0))}export function makeScale(n,c,e){return set(n,c,0,0,e,0,0)}export function translate(n,c,e){return multiply(n,set(M,1,0,0,1,c,e))}export function compose(n,c,e,t,i,u,p,x){const o=Math.sin(u),h=Math.cos(u);return n[0]=t*h,n[1]=i*o,n[2]=-t*o,n[3]=i*h,n[4]=p*t*h-x*t*o+c,n[5]=p*i*o+x*i*h+e,n}export function composeCssTransform(n,c,e,t,i,u,p){return toString(compose(create(),n,c,e,t,i,u,p))}export function invert(n){return makeInverse(n,n)}export function makeInverse(n,c){const e=determinant(c);A(e!==0,"Transformation matrix cannot be inverted");const t=c[0],i=c[1],u=c[2],p=c[3],x=c[4],o=c[5];return n[0]=p/e,n[1]=-i/e,n[2]=-u/e,n[3]=t/e,n[4]=(u*o-p*x)/e,n[5]=-(t*o-i*x)/e,n}export function determinant(n){return n[0]*n[3]-n[1]*n[2]}const k=[1e6,1e6,1e6,1e6,2,2];export function toString(n){return"matrix("+n.map((e,t)=>Math.round(e*k[t])/k[t]).join(", ")+")"}
